using System;using System.IO;using System.Linq;using System.Collections;using System.Collections.Generic;using UnityEngine;using IdleRestaurant;using TMPro;
public static class CleanupFinalUI053 {static RestaurantApp app;public static void Main(){app=UnityEngine.Object.FindAnyObjectByType<RestaurantApp>();Application.runInBackground=true;app.StartCoroutine(Run());}static IEnumerator Run(){string old=Newtonsoft.Json.JsonConvert.SerializeObject(app.Game.State);var checks=new List<string>();try{app.Game.State=new RestaurantGame(app.catalog,Newtonsoft.Json.JsonConvert.DeserializeObject<SaveState>(File.ReadAllText("Recordings/CleanupPacing053/earned-session-save.json"))).State;app.Game.State.largeText=false;app.Navigate("play");app.world.Show(app.Game.State.selected);yield return new WaitForSecondsRealtime(.3f);foreach(bool large in new[]{false,true}){app.Game.State.largeText=large;app.Navigate("play");yield return new WaitForSecondsRealtime(.3f);Canvas.ForceUpdateCanvases();var hint=GameObject.Find("Next restaurant progress").GetComponent<TMP_Text>();hint.ForceMeshUpdate();if(hint.isTextOverflowing||hint.textInfo.lineCount>2)throw new Exception("Growth hint overflows: "+hint.fontSize+" "+hint.textInfo.lineCount);checks.Add("Growth price/services/upgrades fit two lines with largeText="+large);}
app.Game.State.largeText=false;app.Navigate("play");yield return new WaitForSecondsRealtime(.3f);var status=GameObject.Find("Janitor status").GetComponentInChildren<TMP_Text>();if(status.fontSize<24)throw new Exception("Cleanup status too small");checks.Add("Cleanup status uses readable 24-point text");var oldUpgrade=typeof(RestaurantApp).GetMethod("UpgradeResult",System.Reflection.BindingFlags.NonPublic|System.Reflection.BindingFlags.Instance);oldUpgrade.Invoke(app,new object[]{0});yield return null;var label=UnityEngine.Object.FindObjectsByType<TMP_Text>(FindObjectsSortMode.None).FirstOrDefault(t=>t.name=="Upgrade purpose");checks.Add("Upgrade feedback invoked after unsupported checkmark removal");yield return new WaitForSecondsRealtime(2.4f);yield return new WaitForEndOfFrame();var tex=new Texture2D(Screen.width,Screen.height,TextureFormat.RGB24,false);tex.ReadPixels(new Rect(0,0,tex.width,tex.height),0,0);tex.Apply();File.WriteAllBytes("/Users/playnoob/Desktop/Mahnul/GPT/restaurant-v053-cleanup/FinalUI.png",tex.EncodeToPNG());UnityEngine.Object.Destroy(tex);File.WriteAllText("/Users/playnoob/Desktop/Mahnul/GPT/restaurant-v053-cleanup/FinalUI.json",Newtonsoft.Json.JsonConvert.SerializeObject(new{status="PASS",checks,scope="Focused live final UI checks loaded from actual earned playtest save; normal and large text; UI-only changes after pacing"},Newtonsoft.Json.Formatting.Indented));}finally{app.Game.State=new RestaurantGame(app.catalog,Newtonsoft.Json.JsonConvert.DeserializeObject<SaveState>(old)).State;app.Navigate("play");app.world.Show(app.Game.State.selected);app.Save();}}}
